prompts.push({
  // Fall back to a synthetic P-N id when there's no prompt_id column (or the cell is blank) — every row stays addressable.
  id: columnMap.prompt_id ? String(row[columnMap.prompt_id] || `P-${i + 1}`) : `P-${i + 1}`,
  prompt: promptText.trim(),
  category: columnMap.category ? String(row[columnMap.category] || '') : undefined,
  // difficulty defaults to 'medium' — it's the fallback complexity signal the word-count check relies on.
  difficulty: columnMap.difficulty ? (String(row[columnMap.difficulty] || 'medium') as 'easy'|'medium'|'hard') : 'medium',
  // Whitelist-validate: only S/M/L/XL is accepted; any junk value becomes undefined (no explicit size target) rather than a bad enum.
  responseSize: ['S','M','L','XL'].includes(responseSizeRaw.toUpperCase())
    ? responseSizeRaw.toUpperCase() as 'S'|'M'|'L'|'XL' : undefined,
  followUpExpected: ['none','optional','expected'].includes(followUpExpectedRaw.toLowerCase())
    ? followUpExpectedRaw.toLowerCase() as 'none'|'optional'|'expected' : undefined,
});

// \u26A0\uFE0F  We cannot inject into the assistant's actual rulebook layer — that's platform-controlled.
// Instead, the draft rulebook is PREPENDED to the user message inside explicit markers, which cue the
// model to treat the draft as standing instructions — the closest approximation to a real system prompt:
const messageToApp = systemPromptText
  ? `[SYSTEM CONTEXT]\n${systemPromptText}\n\n[USER MESSAGE]\n${prompt.prompt}`
  : prompt.prompt; // Baseline: no draft => bare prompt with NO wrapper, so it measures true no-instruction behavior.

const response = await this.getAppResponse(messageToApp, input.model);

const WORD_COUNT_THRESHOLDS = {
  simple:   { target: 80,  warn: 120, fail: 200 },
  moderate: { target: 150, warn: 220, fail: 320 },
  complex:  { target: 250, warn: 350, fail: 500 },
};

private checkWordCount(response: string, prompt: UserPrompt): WordCountCheck {
  // filter(Boolean) drops empty tokens from leading/multiple whitespace so padding can't inflate the count.
  const wordCount = response.split(/\s+/).filter(Boolean).length;
  // responseSize-first, difficulty-fallback: S/M -> simple/moderate, any OTHER set size (L/XL) -> complex,
  // and only an UNDEFINED responseSize falls back to difficulty (easy/hard, else moderate).
  const complexity = prompt.responseSize === 'S' ? 'simple'
    : prompt.responseSize === 'M' ? 'moderate'
    : prompt.responseSize ? 'complex'
    : prompt.difficulty === 'easy' ? 'simple'
    : prompt.difficulty === 'hard' ? 'complex' : 'moderate';

  const t = WORD_COUNT_THRESHOLDS[complexity];
  // ok at <=target, else warn up through t.fail, else fail — note t.warn is NOT consulted; warn = target..fail band.
  const flag = wordCount <= t.target ? 'ok' : wordCount <= t.fail ? 'warn' : 'fail';
  return { wordCount, complexity, target: t.target, flag } as WordCountCheck;
}

private parseFollowUps(response: string): FollowUpAnalysis {
  const followUpPatterns = [/would you like\s.+\??/gi, /do you want\s.+\??/gi, /want me to\s.+\??/gi];
  const items: string[] = [];
  for (const pattern of followUpPatterns) {
    // `|| []` guards the null String.match returns on no hit, so the spread never throws.
    items.push(...(response.match(pattern) || []).map(m => m.trim()));
  }
  // Dedup (a repeated nudge collapses to one), then cap at 10 to bound pathological replies.
  const unique = Array.from(new Set(items)).slice(0, 10);

  // Cheap question-vs-action heuristic: a '?' ending or an interrogative-verb prefix reads as a question.
  const types = unique.map(item =>
    (item.endsWith('?') || /^(would|do|should|shall|can)\b/i.test(item)) ? 'question' : 'action'
  );
  // Bright line at 3: both withinLimit and the note key off it — >3 follow-ups reads as pushy.
  return { count: unique.length, items: unique, types, withinLimit: unique.length <= 3,
           note: unique.length <= 3 ? 'within limit' : 'exceeds recommended limit of 3' };
}

const OPT_DIMENSION_RUBRICS = {
  conciseness: 'Is the response length appropriate for the query complexity? ...',
  // Explicit breakpoints pin the scale so the judge doesn't drift run-to-run (a classic LLM-as-judge failure).
  follow_up_quality: 'Score follow-up suggestions using explicit breakpoints: 10 = none needed and none shown, ...',
  conversational_tone: 'Is the tone natural and non-overwhelming? Penalise unneeded tables or heavy markdown ...',
  // ...accuracy, response_relevance, hallucination_resistance
};

private async evaluateOptDimensions(prompt, response, followUpAnalysis, wordCountCheck, ...) {
  // Inject the DETERMINISTIC counts as context so the judge grades conciseness/follow-ups against hard numbers,
  // not its own unreliable eyeballing of length or nudge count.
  const judgePrompt = `Score each dimension 1-10 using these rubrics:\n` +
    `1. accuracy — ...\n2. response_relevance — ...\n3. conciseness — ${OPT_DIMENSION_RUBRICS.conciseness}\n` +
    `...\nFOLLOW-UP CONTEXT: ${followUpAnalysis.count} follow-up(s) detected...\n` +
    `WORD COUNT CONTEXT: ${wordCountCheck.wordCount} words, target \u2264${wordCountCheck.target}...`;
  // Same defensive first-{...}-block extraction as the other judges — guards prose-wrapped JSON (flat objects only).
  const rawScores = JSON.parse((await judgeClient.chat(judgePrompt)).response.answer.match(/\{[^}]+\}/)[0]);
  // ...normalize each 1-10 score to 0-1 and average across the 6 dimensions
}

private buildOptSummary(datasetId, model, systemPromptLabel, systemPromptPath, duration, results: PromptOptResult[]): OptRunSummary {
  const verdictCounts = { PASS: 0, WARNING: 0, FAIL: 0 };
  for (const r of results) verdictCounts[r.verdict]++;

  // ?? 0: a dimension the judge omitted counts as 0 — a malformed reply drags the mean down, never skews it up or throws.
  const dimAvg = (dim: OptDimension) => avg(
    results.map(r => r.optScores.dimensions.find(d => d.dimension === dim)?.normalizedScore ?? 0)
  );

  // Keyed by systemPromptLabel so each draft's summary is one row that lines up directly against baseline/other drafts.
  return {
    systemPromptLabel,
    totalPrompts: results.length,
    verdictCounts, // discrete PASS/WARNING/FAIL histogram...
    averageScores: {
      // ...alongside continuous per-dimension means that show WHERE a draft moved the needle.
      conciseness: dimAvg('conciseness'),
      follow_up_quality: dimAvg('follow_up_quality'),
      conversational_tone: dimAvg('conversational_tone'),
      aggregate: avg(results.map(r => r.aggregateScore)),
    },
    avgWordCount: avg(results.map(r => r.wordCount)),
    avgFollowUpCount: avg(results.map(r => r.followUpAnalysis.count)),
  } as OptRunSummary;
}
